#pragma once
// Search engine logos (each site's own favicon, resized to 44x44 PNG, base64). Empty = letter fallback.
#include "Data.h"
inline std::wstring EngineLogo(const std::wstring& n) {
    if (n == L"Google") return L"";
    if (n == L"DuckDuckGo") return L"";
    if (n == L"Bing") return L"";
    if (n == L"Brave") return L"";
    if (n == L"Yahoo") return L"";
    if (n == L"Startpage") return L"";
    if (n == L"Ecosia") return L"";
    if (n == L"Qwant") return L"";
    if (n == L"Perplexity") return L"";
    if (n == L"Copilot") return L"";
    if (n == L"You.com") return L"";
    return L"";
}
